@router.get('/history')
async def get_monitor_history(
    range: str = Query('1h', description='时间范围: 1h, 3h, 6h, 12h, 24h, 7d, 30d'),
    limit: int = Query(500, description='最大返回数据点数'),
):
    """从 SQLite metrics 表读取历史监控数据。"""
    from agent_runtime.core.db import Database
    from pathlib import Path
    from datetime import datetime

    H, D = 3600, 86400
    range_seconds = {
        '1h': H, '3h': 3*H, '6h': 6*H, '12h': 12*H, '24h': D,
        '7d': 7*D, '30d': 30*D,
    }
    secs = range_seconds.get(range, 3600)
    now = time.time()
    start_ts = now - secs

    # 查找数据库路径（优先使用环境变量）
    runtime_home = os.environ.get('AGENT_RUNTIME_HOME')
    if runtime_home:
        db_path = Path(runtime_home) / 'agent.db'
    else:
        db_path = Path(__file__).resolve().parent.parent.parent / 'data' / 'agent.db'
        if not db_path.exists():
            db_path = Path.home() / '.openchiip-harness' / 'agent.db'
    if not db_path.exists():
        return {'times': [], 'cpu': [], 'memory_percent': [], 'load_avg_1': [],
                'load_avg_5': [], 'load_avg_15': [], 'disk_read': [], 'disk_write': [],
                'network_rx': [], 'network_tx': [], 'process_count': [], 'range': range}

    db = Database(str(db_path))
    rows = db.get_metrics_range(start_ts=start_ts, end_ts=now, limit=limit)

    times, cpu, mem_pct = [], [], []
    load1, load5, load15 = [], [], []
    disk_r, disk_w = [], []
    net_rx, net_tx = [], []
    proc = []

    def _v(row, key, rnd=None):
        v = row.get(key)
        return None if v is None else (round(v, rnd) if rnd else v)

    for r in rows:
        ts = r.get('timestamp', 0)
        if isinstance(ts, str):
            try:
                ts_ms = int(datetime.fromisoformat(ts).timestamp() * 1000)
            except Exception:
                ts_ms = ts
        else:
            ts_ms = int(ts * 1000)

        times.append(ts_ms)
        cpu.append(_v(r, 'cpu', 1))
        mem_pct.append(_v(r, 'memory', 1))
        load1.append(_v(r, 'load_avg_1', 2))
        load5.append(_v(r, 'load_avg_5', 2))
        load15.append(_v(r, 'load_avg_15', 2))
        disk_r.append(_v(r, 'disk_read'))
        disk_w.append(_v(r, 'disk_write'))
        net_rx.append(_v(r, 'network_rx'))
        net_tx.append(_v(r, 'network_tx'))
        proc.append(_v(r, 'process_count'))

    return {
        'times': times,
        'cpu': cpu,
        'memory_percent': mem_pct,
        'load_avg_1': load1,
        'load_avg_5': load5,
        'load_avg_15': load15,
        'disk_read': disk_r,
        'disk_write': disk_w,
        'network_rx': net_rx,
        'network_tx': net_tx,
        'process_count': proc,
        'range': range,
    }
